'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var reinterpret = require( '@stdlib/strided/base/reinterpret-complex128' );
var loopOrder = require( '@stdlib/ndarray/base/nullary-loop-interchange-order' );
var real = require( '@stdlib/complex/float64/real' );
var imag = require( '@stdlib/complex/float64/imag' );
var min = require( '@stdlib/math/base/special/fast/min' );


// FUNCTIONS //

/**
* Initializes all elements of matrix `A` to given values.
*
* @private
* @param {NonNegativeInteger} M - number of rows in matrix `A`
* @param {NonNegativeInteger} N - number of columns in matrix `A`
* @param {Complex128} alpha - value assigned to off-diagonal elements
* @param {Complex128} beta - value assigned to diagonal elements
* @param {Complex128Array} A - input matrix
* @param {integer} strideA1 - stride of the first dimension of `A`
* @param {integer} strideA2 - stride of the second dimension of `A`
* @param {NonNegativeInteger} offsetA - starting index for `A`
* @returns {Complex128Array} `A`
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* setAll( 2, 2, alpha, beta, A, 2, 1, 0 );
* var z = A.get( 0 );
*
* real( z )
* // => 3.0
*
* imag( z )
* // => 4.0
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
*
* setAll( 2, 2, alpha, beta, A, 2, -1, 1 );
*
* var z = A.get( 0 );
*
* real( z )
* // => 1.0
*
* imag( z )
* // => 2.0
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
* setAll( 2, 2, alpha, beta, A, -2, 1, 2 );
* var z = A.get( 0 );
*
* real( z )
* // => 1.0
*
* imag( z )
* // => 2.0
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
* setAll( 2, 2, alpha, beta, A, -2, -1, 3 );
* var z = A.get( 0 );
*
* real( z )
* // => 3.0
*
* imag( z )
* // => 4.0
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
*
* setAll( 2, 2, alpha, beta, A, 1, 2, 0 );
* var z = A.get( 0 );
*
* real( z )
* // => 3.0
*
* imag( z )
* // => 4.0
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
* setAll( 2, 2, alpha, beta, A, -1, 2, 1 );
* var z = A.get( 0 );
*
* real( z )
* // => 1.0
*
* imag( z )
* // => 2.0
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
* setAll( 2, 2, alpha, beta, A, 1, -2, 2 );
* var z = A.get( 0 );
*
* real( z )
* // => 1.0
*
* imag( z )
* // => 2.0
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
* setAll( 2, 2, alpha, beta, A, -1, -2, 3 );
* var z = A.get( 0 );
*
* real( z )
* // => 3.0
*
* imag( z )
* // => 4.0
*/
function setAll( M, N, alpha, beta, A, strideA1, strideA2, offsetA ) {
	var alphar;
	var alphai;
	var betar;
	var betai;
	var viewA;
	var da0;
	var da1;
	var sh;
	var S0;
	var S1;
	var sa;
	var ia;
	var i0;
	var i1;
	var o;

	alphar = real( alpha );
	alphai = imag( alpha );
	betar = real( beta );
	betai = imag( beta );

	// Resolve the loop interchange order:
	o = loopOrder( [ M, N ], [ strideA1, strideA2 ] );
	sh = o.sh;
	sa = o.sx;

	// Extract loop variables for purposes of loop interchange: dimensions and loop offset (pointer) increments...
	S0 = sh[ 0 ];
	S1 = sh[ 1 ];

	// Premultiply float64 strides by 2
	da0 = sa[ 0 ]*2;
	da1 = (sa[ 1 ] - ( S0*sa[0] )) * 2;

	viewA = reinterpret( A, 0 );

	// Set the pointers to the first indexed elements in the respective matrices...
	ia = offsetA * 2;

	// Iterate over the matrix dimensions...
	for ( i1 = 0; i1 < S1; i1++ ) {
		for ( i0 = 0; i0 < S0; i0++ ) {
			if ( i0 === i1 ) {
				viewA[ ia ] = betar;
				viewA[ ia+1 ] = betai;
			} else {
				viewA[ ia ] = alphar;
				viewA[ ia+1 ] = alphai;
			}
			ia += da0;
		}
		ia += da1;
	}
	return A;
}

/**
* Initializes the upper triangular/trapezoidal part of a matrix `A` to given values.
*
* @private
* @param {NonNegativeInteger} M - number of rows in matrix `A`
* @param {NonNegativeInteger} N - number of columns in matrix `A`
* @param {Complex128} alpha - value assigned to off-diagonal elements
* @param {Complex128} beta - value assigned to diagonal elements
* @param {Complex128Array} A - input matrix
* @param {integer} strideA1 - stride of the first dimension of `A`
* @param {integer} strideA2 - stride of the second dimension of `A`
* @param {NonNegativeInteger} offsetA - starting index for `A`
* @returns {Complex128Array} `A`
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
*
* setUpper( 2, 2, alpha, beta, A, 2, 1, 0 );
* var z = A.get( 0 );
*
* real( z )
* // => 3.0
*
* imag( z )
* // => 4.0
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
*
* setUpper( 2, 2, alpha, beta, A, 2, -1, 1 );
* var z = A.get( 0 );
*
* real( z )
* // => 1.0
*
* imag( z )
* // => 2.0
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
*
* setUpper( 2, 2, alpha, beta, A, -2, 1, 2 );
* var z = A.get( 0 );
*
* real( z )
* // => 0.0
*
* imag( z )
* // => 0.0
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
*
* setUpper( 2, 2, alpha, beta, A, -2, -1, 3 );
* var z = A.get( 0 );
*
* real( z )
* // => 3.0
*
* imag( z )
* // => 4.0
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
*
* setUpper( 2, 2, alpha, beta, A, 1, 2, 0 );
* var z = A.get( 0 );
*
* real( z )
* // => 3.0
*
* imag( z )
* // => 4.0
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
*
* setUpper( 2, 2, alpha, beta, A, -1, 2, 1 );
* var z = A.get( 0 );
*
* real( z )
* // => 0.0
*
* imag( z )
* // => 0.0
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
*
* setUpper( 2, 2, alpha, beta, A, 1, -2, 2 );
* var z = A.get( 0 );
*
* real( z )
* // => 1.0
*
* imag( z )
* // => 2.0
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
*
* var A = new Complex128Array( 4 );
* var alpha = new Complex128( 1.0, 2.0 );
* var beta = new Complex128( 3.0, 4.0 );
*
* setUpper( 2, 2, alpha, beta, A, -1, -2, 3 );
* var z = A.get( 0 );
*
* real( z )
* // => 3.0
*
* imag( z )
* // => 4.0
*/
function setUpper( M, N, alpha, beta, A, strideA1, strideA2, offsetA ) {
	var alphar;
	var alphai;
	var betar;
	var betai;
	var viewA;
	var idx;
	var sa1;
	var sa2;
	var ia;
	var i0;
	var i1;

	alphar = real( alpha );
	alphai = imag( alpha );
	betar = real( beta );
	betai = imag( beta );

	viewA = reinterpret( A, 0 );

	// Premultiply float64 strides by 2
	ia = offsetA * 2;
	sa1 = strideA1 * 2;
	sa2 = strideA2 * 2;

	if ( isRowMajor( [ strideA1, strideA2 ] ) ) {
		for ( i1 = 0; i1 < M; i1++ ) {
			idx = ia+(i1*sa2);
			for ( i0 = i1; i0 < N; i0++ ) {
				if ( i0 === i1 ) {
					viewA[ idx ] = betar;
					viewA[ idx+1 ] = betai;
				} else {
					viewA[ idx ] = alphar;
					viewA[ idx+1 ] = alphai;
				}
				idx += sa2;
			}
			ia += sa1;
		}
		return A;
	}
	for ( i1 = 0; i1 < N; i1++ ) {
		idx = ia;
		for ( i0 = 0; i0 <= min( i1, M-1 ); i0++ ) {
			if ( i0 === i1 ) {
				viewA[ idx ] = betar;
				viewA[ idx+1 ] = betai;
			} else {
				viewA[ idx ] = alphar;
				viewA[ idx+1 ] = alphai;
			}
			idx += sa1;
		}
		ia += sa2;
	}
	return A;
}

