	var alphar;
	var alphai;
	var betar;
	var betai;
	var viewA;
	var sa1;
	var sa2;
	var idx;
	var ia;
	var i0;
	var i1;

	alphar = real( alpha );
	alphai = imag( alpha );
	betar = real( beta );
	betai = imag( beta );

	viewA = reinterpret( A, 0 );

	// Premultiply float64 strides by 2
	ia = offsetA * 2;
	sa1 = strideA1 * 2;
	sa2 = strideA2 * 2;

	if ( isRowMajor( [ strideA1, strideA2 ] ) ) {
		for ( i1 = 0; i1 < M; i1++ ) {
			idx = ia;
			for ( i0 = 0; i0 <= min( i1, N-1 ); i0++ ) {
				if ( i0 === i1 ) {
					viewA[ idx ] = betar;
					viewA[ idx+1 ] = betai;
				} else {
					viewA[ idx ] = alphar;
					viewA[ idx+1 ] = alphai;
				}
				idx += sa2;
			}
			ia += sa1;
		}
		return A;
	}
	for ( i1 = 0; i1 < N; i1++ ) {
		idx = ia+(i1*sa1);
		for ( i0 = i1; i0 < M; i0++ ) {
			if ( i0 === i1 ) {
				viewA[ idx ] = betar;
				viewA[ idx+1 ] = betai;
			} else {
				viewA[ idx ] = alphar;
				viewA[ idx+1 ] = alphai;
			}
			idx += sa1;
		}
		ia += sa2;
	}
